// Regenerates packages/api/src/gen from ../hub/contracts and records the hub commit in .contracts-version.
// Never hand-edit the generated files — change ../hub/contracts and rerun `pnpm codegen`.
import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const hub = resolve(root, '../hub')
const spec = resolve(hub, 'contracts/openapi.yaml')
const outDir = resolve(root, 'packages/api/src/gen')

if (!existsSync(spec)) {
  console.error(`Contract not found: ${spec}\nThe hub must sit next to this repo (../hub).`)
  process.exit(1)
}

const git = (...args) => execFileSync('git', ['-C', hub, ...args], { encoding: 'utf8' }).trim()
const commit = git('rev-parse', 'HEAD')
const dirty = git('status', '--porcelain', '--', 'contracts') !== ''
const version = dirty ? `${commit}-dirty` : commit

const ast = await openapiTS(pathToFileURL(spec))
const header = [
  '// AUTO-GENERATED by `pnpm codegen` from ../hub/contracts/openapi.yaml — DO NOT EDIT.',
  `// Hub commit: ${version}`,
  '',
].join('\n')

mkdirSync(outDir, { recursive: true })
writeFileSync(resolve(outDir, 'schema.d.ts'), header + astToString(ast))
writeFileSync(resolve(root, '.contracts-version'), version + '\n')

console.log(`Generated packages/api/src/gen/schema.d.ts from hub ${version}`)
if (dirty)
  console.warn(
    'Warning: hub contracts have uncommitted changes; commit them in the hub before committing here.',
  )
